  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["FCC2", "NAVC2", "R25"],
      "pins": ["FCC2.48 (VCAP)", "FCC2.73 (VCAP)", "NAVC2.31 (VCAP_1)", "NAVC2.47 (VCAP_2)"],
      "nets": ["NET0065", "NET0084", "NET0075", "NET0088"],
      "observed": "The STM32 VCAP pins are connected to external signal nets rather than isolated and decoupled: FCC2.48 NET0065 runs through R25 to NET0067, FCC2.73 NET0084 reaches a board connector, and NAVC2.31 NET0075 and NAVC2.47 NET0088 share nets with USB signals. No VCAP capacitors are shown.",
      "expected": "Each MCU VCAP pin should have its required capacitor to ground and should not be connected to GPIO, connector, or USB signal nets.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "VCAP 48 NET0065; VCAP 73 NET0084 — FCC sheet, page 2"
        },
        {
          "source": "schematic",
          "quote": "NET0065 — R25 10 — NET0067; NET0084 on UART3_FCC2 connector — Connections sheet, page 4"
        },
        {
          "source": "schematic",
          "quote": "VCAP_1 31 NET0075; VCAP_2 47 NET0088 — NAVC sheet, page 3"
        },
        {
          "source": "schematic",
          "quote": "USB5 D- NET0075; USB5 ID NET0088 — Connections sheet, page 4"
        }
      ],
      "impact": "The MCU internal core-regulator outputs are loaded by external signal circuitry and lack required stabilization capacitors. This can prevent reliable MCU operation and may cause failures on the connected GPIO or USB interfaces.",
      "confidence": 0.99
    }
  ],
  "summary": "The VCAP pins of both MCUs are improperly connected to external signal nets and have no shown required capacitors. This is a substantive connectivity error likely to impair MCU operation."
}

